def rot180(grid):
    """The grid rotated by 180 degrees."""
    return [row[::-1] for row in grid[::-1]]

def opposite_block(grid):
    """The 4x4 block diametrically opposite the 3-colored block, rotated 180 degrees."""
    cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    h=rs[-1]-rs[0]+1; w=cs[-1]-cs[0]+1
    top=len(grid)-rs[-1]-1; left=len(grid[0])-cs[-1]-1
    return rot180(crop(grid, top, left, h, w))

def crop(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

